import{_ as r,l as c,o as a,c as o,v as i,p as s,x as t,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"nice 与权重","description":"","frontmatter":{"title":"nice 与权重","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nice-weight.md","filePath":"cs/nice-weight.md","lastUpdated":1789023840000}'),h={name:"cs/nice-weight.md"};function m(_,e,u,f,E,C){const n=c("Mermaid");return a(),o("div",null,[e[1]||(e[1]=i('<h1 id="nice-与权重" tabindex="-1">nice 与权重 <a class="header-anchor" href="#nice-与权重" aria-label="Permalink to &quot;nice 与权重&quot;">​</a></h1><div class="epigraph"><p>nice 是用户能拧的相对权重旋钮：数越大越「客气」，折算后同一墙钟里分到的 CPU 更少。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, LKD 对 nice 的整理</footer></div><p><a href="/cs/cfs-vruntime">上一课</a>让调度器比较折算后的虚拟时间。缺口是权重 \\(w_i\\) 从哪来。Unix 把用户接口做成 <strong>nice</strong>：默认 0，范围通常 -20 到 19，映射到内部权重表，再进入 vruntime 增量。本课只钉这层映射与「相对份额」，不把多核负载数写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CFS 的目标是份额 \\(w_i/\\sum w\\)，不是固定优先级抢占。用户不能也不该直接写内核权重整数；nice 提供粗档。同一 nice 的任务彼此仍按 vruntime 公平。缺口不是记账公式，而是：<strong>改 nice 只改增量快慢，不把别人从 CPU 上绝对踢走</strong>（除非实时策略另说）。</p><p><span class="marginnote">nice +19 不是停止运行；可运行集合里若只有它，它仍得全部 CPU。权重是相对的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查表：nice 越低（更负）权重越大，同样 \\(\\Delta t\\) 里 vruntime 涨得越慢，越容易保持「最小」。权限：降低 nice（更贪）通常要特权，升高（更客气）谁都可以——防止普通人把自己调成实时杀手。本课不把具体表项数字当定律，只要求单调。</p>',8)),(a(),s(p,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NICE%5B%22nice%20%E5%80%BC%22%5D%20--%3E%20W%5B%22%E5%86%85%E9%83%A8%E6%9D%83%E9%87%8D%22%5D%0A%20%20W%20--%3E%20VR%5B%22vruntime%20%E5%A2%9E%E9%87%8F%22%5D%0A%20%20VR%20--%3E%20SHARE%5B%22%E7%9B%B8%E5%AF%B9%20CPU%20%E4%BB%BD%E9%A2%9D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>与<a href="/cs/mlfq">MLFQ</a> 对照：nice 是显式用户意图；MLFQ 档位是内核猜的行为。两者可同时存在于不同系统，本课对象是权重。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>权重让后台编译 <code>nice +10</code> 而不必用实时优先级去「压」它：前台仍按更高权重摊时间。指标上，这是公平尺子的加权版，不是周转最优。I/O 型即使 nice 较高，也常因 vruntime 停住而保持响应——与上一课一致。</p><p>组调度（按 tty 或 cgroup 再摊一层）是后话；本课默认权重在任务一级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>SCHED_IDLE</code>、<code>SCHED_BATCH</code> 的全部语义写完，不讨论容器 CPU 限额与 nice 谁说了算的政策冲突。实时优先级不是 nice 的延伸：那是另一套调度类，对照课已经分开。</p><p>后课默认：单核上权重决定份额。多核上每 CPU 一条队列，份额会被队列长度扭曲，除非迁移，下一课讲负载均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>nice 映射到权重；份额相对，不是绝对禁跑。</li><li>更负的 nice 让 vruntime 走得更慢。</li><li>跨 CPU 搬任务是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',9))])}const S=r(h,[["render",m]]);export{D as __pageData,S as default};
